head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > titleFormatter]<br/>Body 영역의 각 Cell 에 title 속성을 동적 생성하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "titleFormatter 속성을 설정하면 titleAuto 속성은 무시됩니다.",
        "사용자 정의 함수를 설정하면 각 Cell 의 title 속성값을 생성하며, 함수는 처리중인 Cell 의 Row 인덱스, Column 인덱스, Cell 의 원본값을 파라미터로 전달받고 반환값이 처리중인 Cell 의 title 속성값으로 적용됩니다.",
        "반환값을 생략하면 처리중인 Cell 의 title 속성값에 undefined 가 설정됩니다.",
        "titleFormatter 속성에 설정된 사용자 정의 함수는 Body 영역의 전체 Cell 에 적용됩니다.",
        "SubTotal Row 에는 적용되지 않습니다.",
        "Cell 의 inputType 속성값이 'expression','drilldown','spinner','custom' 인 경우엔 사용자 정의 함수가 동작하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 값 읽기 (미설정이면 속성 미부여 = 기본값)
    let titleFormatterVal = con_titleFormatter.getValue();
    let titleAutoVal = con_titleAuto.getValue();

    // 동작 조건/현재 설정 라벨 생성
    $c.gcm.createLabel('label="titleFormatter 함수는 각 Cell 의 Row 인덱스, Column 인덱스, 원본값을 받아 title 을 생성합니다."', '', 'label1');
    $c.gcm.createLabel('label="현재 설정: titleFormatter=' + (titleFormatterVal === '' ? '미설정' : '설정') + ' / titleAuto=' + (titleAutoVal === '' ? '미설정' : titleAutoVal) + '"', '', 'label2');

    // dataList 직접 생성 (그룹 기준 dept 가 연속되도록 정렬, 빈 행 0)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="colExpr" name="colExpr" dataType="number"></w2:column>';
    strDl += '<w2:column id="colDrill" name="colDrill" dataType="text"></w2:column>';
    strDl += '<w2:column id="colSpin" name="colSpin" dataType="number"></w2:column>';
    strDl += '<w2:column id="colCust" name="colCust" dataType="text"></w2:column>';
    strDl += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    // [dept, col1, col2, col3, colExpr, colDrill, colSpin, colCust, amount]
    // col3 에는 각 행 실제(비어있지 않은) 값(Val0~Val3)을 부여 → 셀 데이터는 존재하지만
    // titleFormatter 함수가 col3 분기에서 반환값을 생략하므로 title=undefined 가 됨을 명확히 실증
    // colSpin(숫자: 1,2,3,4)을 expression 컬럼(colExpr)이 참조 (colExpr = colSpin * 100)
    let rows = [
        ['Sales', 'Apple',  'Banana', 'Val0', 10, 'Drill1', 1, 'Cust1', 100],
        ['Sales', 'Grape',  'Melon',  'Val1', 20, 'Drill2', 2, 'Cust2', 200],
        ['Dev',   'Orange', 'Peach',  'Val2', 30, 'Drill3', 3, 'Cust3', 300],
        ['Dev',   'Mango',  'Kiwi',   'Val3', 40, 'Drill4', 4, 'Cust4', 400]
    ];
    for (let r = 0; r < rows.length; r++) {
        strDl += '<w2:row>';
        strDl += '<dept><![CDATA[' + rows[r][0] + ']]></dept>';
        strDl += '<col1><![CDATA[' + rows[r][1] + ']]></col1>';
        strDl += '<col2><![CDATA[' + rows[r][2] + ']]></col2>';
        strDl += '<col3><![CDATA[' + rows[r][3] + ']]></col3>';
        strDl += '<colExpr><![CDATA[' + rows[r][4] + ']]></colExpr>';
        strDl += '<colDrill><![CDATA[' + rows[r][5] + ']]></colDrill>';
        strDl += '<colSpin><![CDATA[' + rows[r][6] + ']]></colSpin>';
        strDl += '<colCust><![CDATA[' + rows[r][7] + ']]></colCust>';
        strDl += '<amount><![CDATA[' + rows[r][8] + ']]></amount>';
        strDl += '</w2:row>';
    }
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // titleFormatter / titleAuto 속성 (미설정 시 속성 미부여 = 기본값)
    // titleFormatter 설정 시: scwin.target1_titleFormatter 함수를 부여
    let titleFormatterAttr = titleFormatterVal === '' ? '' : 'titleFormatter="scwin.target1_titleFormatter" ';
    let titleAutoAttr = titleAutoVal === '' ? '' : 'titleAuto="' + titleAutoVal + '" ';

    // target 생성 (Header inputType=text + Body inputType 혼합 + SubTotal Row)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + titleFormatterAttr + titleAutoAttr + 'checkAllType="false" dataList="data:dlt_bind" id="" style="width:980px;height:320px;">';
    strTarget += '<w2:caption style="" id="caption1" value="titleFormatter 테스트 그리드"></w2:caption>';
    // Header : 모든 컬럼 inputType=text
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="90"  inputType="text" id="hdept" value="부서"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="hcol1" value="텍스트1"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="hcol2" value="텍스트2"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="hcol3" value="반환생략"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="hcolExpr" value="expression"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="hcolDrill" value="drilldown"></w2:column>';
    strTarget += '<w2:column width="90"  inputType="text" id="hcolSpin" value="spinner"></w2:column>';
    strTarget += '<w2:column width="*"   inputType="text" id="hcolCust" value="custom"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // Body : inputType 혼합 (text 3 + expression/drilldown/spinner/custom)
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="90"  inputType="text" dataType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    // V6: expression — titleFormatter 함수 미동작. 식은 숫자 데이터 컬럼 colSpin 을 display() 로 참조(colSpin * 100)하여 각 행 유효 숫자 산출
    strTarget += '<w2:column width="100" inputType="expression" dataType="number" displayFormat="#,###" id="colExpr" expression="Number(display(\'colSpin\')) * 100"></w2:column>';
    // V6: drilldown — 함수 미동작
    strTarget += '<w2:column width="100" inputType="drilldown" dataType="text" id="colDrill" dataList="colDrill"></w2:column>';
    // V6: spinner — 함수 미동작
    strTarget += '<w2:column width="90"  inputType="spinner" dataType="number" viewType="icon" id="colSpin" dataList="colSpin"></w2:column>';
    // V6: custom — 함수 미동작 (typeGetter 로 실제 custom 렌더 구성 → text 폴백 방지, titleFormatter 미적용 실증)
    strTarget += '<w2:column width="*"   inputType="custom" dataType="text" id="colCust" dataList="colCust" typeGetter="scwin.target1_custTypeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    // SubTotal : dept 기준 소계 Row (titleFormatter 가 적용되지 않아야 함 = V5)
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="dept">';
    strTarget += '<w2:row style="" id="srow1">';
    strTarget += '<w2:column width="90"  inputType="text" id="sdept" value="소계"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="scol1" value=""></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="scol2" value=""></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="scol3" value=""></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="scolExpr" value=""></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="scolDrill" value=""></w2:column>';
    strTarget += '<w2:column width="90"  inputType="text" id="scolSpin" value=""></w2:column>';
    strTarget += '<w2:column width="*"   inputType="expression" dataType="number" displayFormat="#,###" id="scolCust" expression="sum(\'amount\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 생성 직후 각 Body Cell 의 title 속성을 읽어 함수 반환값과 비교 출력 (검증 자동 출력)
    scwin.printTitleResult();
}



// titleFormatter 사용자 정의 함수 (con_titleFormatter=설정 시에만 부여)
// 처리중 Cell 의 Row 인덱스, Column 인덱스, Cell 원본값을 파라미터로 전달받고 반환값이 title 로 적용됨
scwin.target1_titleFormatter = function (rowIndex, colIndex, data) {
    if (colIndex === 1) {
        // col1(text) : Row 인덱스 + 원본값
        return 'Row ' + rowIndex + ': ' + data;
    } else if (colIndex === 2) {
        // col2(text) : Amount 라벨 + 원본값
        return 'Amount: ' + data;
    } else if (colIndex === 3) {
        // col3(text) : 셀에 값(data=Val0~Val3)이 존재하지만 사용자 정의 함수가 반환값을 생략 → title 에 undefined 설정 (V3)
        return;
    }
    // 그 외 컬럼(dept 등) : 원본값 그대로 반환
    return data;
};



// colCust(inputType=custom) 셀 타입 동적 구성 함수
// typeGetter 를 지정하여 셀을 실제 custom 렌더(내부 text 컴포넌트)로 구성한다.
// 이로써 custom 컬럼이 text 셀로 폴백되지 않으며, 엔진의 custom setInnerHTML 경로에는
// titleFormatter 호출이 없으므로 colCust 셀에는 title 속성이 적용되지 않는다 (V6 실증).
scwin.target1_custTypeGetter = function (info) {
    // info : { colID, colIndex, rowIndex, realRowIndex } - 셀 원본값을 내부 text 셀로 표시
    return {
        id: 'dynamic_custom_' + info.rowIndex + '_' + info.colIndex,
        inputType: 'text',
        options: { textAlign: 'left' }
    };
};



// 각 Body Cell 의 td title 속성을 읽어 결과창에 출력
scwin.printTitleResult = function () {
    let gridId = scwin.target1.id;
    let titleFormatterVal = con_titleFormatter.getValue();
    let titleAutoVal = con_titleAuto.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("[설정] titleFormatter=" + (titleFormatterVal === '' ? '미설정' : '설정') + " / titleAuto=" + (titleAutoVal === '' ? '미설정' : titleAutoVal));

    // 검증 대상 컬럼 (col1~col3 일반 text + V6 컬럼)
    let cols = [
        { col: 'col1', label: 'text(Row n: data)' },
        { col: 'col2', label: 'text(Amount: data)' },
        { col: 'col3', label: 'text(셀값 존재+반환생략)' },
        { col: 'colExpr', label: 'expression' },
        { col: 'colDrill', label: 'drilldown' },
        { col: 'colSpin', label: 'spinner' },
        { col: 'colCust', label: 'custom(typeGetter→내부 text 셀)' }
    ];

    // Body 데이터 Row 0 의 각 컬럼 title 을 출력 (V2/V3/V4/V6)
    let r = 0;
    for (let i = 0; i < cols.length; i++) {
        let colIdx = scwin.target1.getColumnIndex(cols[i].col);
        let td = document.querySelector("td[id*='" + gridId + "_cell_" + r + "_" + colIdx + "']");
        let titleVal = '(td 미검출)';
        if (td) {
            // td 자체 title 우선, 없으면 내부 요소 title
            let tv = td.getAttribute('title');
            if (tv === null) {
                let inner = td.querySelector('[title]');
                tv = inner ? inner.getAttribute('title') : null;
            }
            titleVal = (tv === null ? '(title 속성 없음)' : "'" + tv + "'");
        }
        // 셀 데이터(원본값)를 함께 출력 → 특히 col3 는 셀에 값이 있어도 함수 반환 생략으로 title=undefined 임을 명확화
        let cellData = scwin.target1.getCellData(r, colIdx);
        wf_body_bottom.getObj("scwin").setReturnValue("[Row" + r + " " + cols[i].label + "] 셀데이터='" + cellData + "' / title=" + titleVal);
    }

    // [엔진/가이드 불일치 보고] custom 컬럼은 typeGetter 로 실제 custom 렌더(내부 text 셀)로 구성되었으나,
    // 내부 위임 셀(비-embedded text)이 grid 의 titleFormatter 를 적용하여 td title 이 설정됨.
    // 반면 expression / drilldown / spinner 는 title 미적용으로 V6 일치. custom 만 가이드와 불일치.
    if (titleFormatterVal !== '') {
        wf_body_bottom.getObj("scwin").setReturnValue("[불일치] custom: 가이드는 사용자 정의 함수 미동작이나, 내부 위임 셀이 titleFormatter 를 적용해 title 이 설정됨 (expression/drilldown/spinner 는 미적용으로 일치)");
    }

    // SubTotal Row 의 셀 title 확인 (V5: 미적용)
    let subTr = document.querySelector("tr[id='srow1']") || document.querySelector("tr[id$='srow1']");
    let subTitleInfo = '(SubTotal Row 미검출)';
    if (subTr) {
        let subTds = subTr.querySelectorAll('td');
        let titled = 0;
        for (let s = 0; s < subTds.length; s++) {
            let tv = subTds[s].getAttribute('title');
            if (tv !== null && tv !== '') titled++;
        }
        subTitleInfo = 'title 가 부여된 셀 수=' + titled + ' / 전체 셀 수=' + subTds.length;
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[SubTotal Row] " + subTitleInfo + " (V5: 0 = title 미적용 기대)");
};
